-- Apply the October 2026 quick-reference wording to the published 2026–2027 rubric.
-- Criterion IDs, keys, weights, score rows, and the calculated Overall Production
-- category remain unchanged.

do $$
declare
  criteria_payload constant jsonb := $criteria$[{"category_key":"music_direction","criteria":[{"sort_order":1,"title":"VOCAL PERFORMANCE: Vocal Technique and Musical Accuracy","description":"• Accurate pitch, secure harmonies, and rhythmic precision\n• Clear diction, breath support, and smooth vocal transitions\n• Consistent technique, unified tone, and intentional vocal shaping across soloists and ensemble\n• Purposeful phrasing and dynamics that support musical expression and the emotional arc"},{"sort_order":2,"title":"STYLISTIC CHOICES: Lyric Interpretation and Emotional Storytelling","description":"• Purposeful phrasing, dynamics, inflection, and vocal tone\n• Nuanced, authentic lyric interpretation that communicates character, intention, and emotion\n• Character-driven vocal choices that advance the narrative for soloists and ensemble\n• Consistent, character-appropriate vocal styles, accents, and dialects when relevant"},{"sort_order":3,"title":"BALANCE AND BLEND: Soloists, Ensemble, Vocal Parts, and Accompaniment","description":"• Balanced soloist and ensemble sound; clear blend among harmonized vocal parts\n• Individual voices and sections heard without unintentionally overpowering others\n• Appropriate musical balance between singers and live or recorded accompaniment\n• Dynamic sensitivity and unified blend that support clarity and storytelling"},{"sort_order":4,"title":"STORY DEPICTION: Pacing, Transitions, and Energy","description":"• Musical pacing, tempo, and energy aligned with dramatic stakes and story progression\n• Seamless movement between dialogue, songs, and musical sections\n• Songs treated as extensions of dialogue and character development\n• Rhythmic vitality, emotional connection, and sustained narrative momentum"}]},{"category_key":"orchestra","criteria":[{"sort_order":1,"title":"MUSICIANSHIP AND TECHNICAL ACCURACY: Intonation, Rhythm, Ensemble Precision","description":"• Accurate intonation, tuning, and rhythmic execution\n• Clean, coordinated entrances, cutoffs, and musical transitions\n• Cohesive ensemble precision and consistent technical control\n• Confident, clear execution appropriate to the score and musical style"},{"sort_order":2,"title":"MUSICAL EXPRESSION AND INTERPRETATION","description":"• Intentional phrasing, articulation, and tonal choices appropriate to the score\n• Expressive dynamics, contrast, and nuance that convey mood and emotional stakes\n• Stylistic consistency appropriate to the production’s genre and setting\n• Unified musical interpretation that strengthens character and storytelling"},{"sort_order":3,"title":"BALANCE, BLEND, AND VOCAL SUPPORT","description":"• Balanced instrumental sections with a cohesive ensemble blend\n• Dynamic sensitivity that supports singers without competing with them\n• Attentiveness to vocal entrances, phrasing, and expressive delivery\n• Appropriate instrumental intensity and texture that preserve musical clarity and emotion"},{"sort_order":4,"title":"INTEGRATION WITH STAGE ACTION AND STORYTELLING","description":"• Musical cues, entrances, and cutoffs coordinated with onstage action\n• Tempo and pacing that complement performers’ dialogue, choreography, and movement\n• Smooth transitions between dialogue, songs, and dramatic moments\n• Responsive accompaniment that supports performer phrasing and dramatic choices while sustaining narrative flow"}]},{"category_key":"choreography","criteria":[{"sort_order":1,"title":"EXECUTION AND SYNCHRONIZATION: Clarity, Precision, Timing, Memorization","description":"• Clear, controlled, and confident execution of movement\n• Accurate rhythmic timing and coordinated ensemble performance\n• Synchronized movement when intended, with clean transitions\n• Consistent memorization, precision, and quality throughout"},{"sort_order":2,"title":"STORYTELLING THROUGH MOVEMENT: Emotional Connection, Narrative Function, Style","description":"• Movement that reveals character intentions, relationships, and emotional subtext\n• Choreography that advances plot, themes, or character development\n• Expressive physicality and movement vocabulary suited to the musical’s style and tone\n• Clear dramatic purpose beyond spectacle or decorative movement"},{"sort_order":3,"title":"USE OF SPACE AND FORMATIONS: Levels, Shapes, Traffic Patterns","description":"• Purposeful use of available space, levels, depth, and spatial relationships\n• Visually clear, varied formations, patterns, and stage pictures\n• Fluid traffic patterns and transitions between formations\n• Appropriate spacing for cast size, with effective use of scenic elements when relevant"},{"sort_order":4,"title":"SAFETY, SUITABILITY, AND PERFORMER ADAPTATION","description":"• Movement appropriately challenging for performers’ abilities and training\n• Safe, controlled, and confident execution of lifts, stage combat, acrobatics, and other demanding elements\n• Thoughtful adaptations that accommodate performers while preserving musical and narrative intent\n• Safe spatial coordination and appropriate handling of theatrical weapons or hazards, when applicable"},{"sort_order":5,"title":"COLLABORATION TO ACHIEVE THE DIRECTOR’S VISION","description":"• Choreographic choices aligned with the director’s artistic vision and storytelling\n• Seamless integration with blocking, staging, and scene transitions\n• Movement coordinated with musical rhythm, phrasing, and dynamics\n• Effective interaction with scenery, props, costumes, and other design elements"}]},{"category_key":"ensemble","criteria":[{"sort_order":1,"title":"CHARACTERIZATION: Commitment and Focus","description":"• Distinct, believable character objectives and intentional choices\n• Consistent focus and immersion, including background moments\n• Authentic listening, reactions, and engagement with fellow performers\n• Individual characterization that enriches atmosphere, relationships, and story"},{"sort_order":2,"title":"SKILL EXECUTION: Vocal Unity and Expressive Support","description":"• Accurate harmonies, cohesive blend, and clear articulation of intelligible lyrics\n• Consistent vocal control, quality, and expressive dynamics\n• Sustained character voice and character-specific vocal choices suited to the scene’s style and emotional tone\n• Individual contributions that strengthen unified musical storytelling"},{"sort_order":3,"title":"MOVEMENT PRECISION AND SPATIAL AWARENESS","description":"• Precise, controlled movement with synchronization when intended\n• Clear spacing, group formations, and awareness of fellow performers\n• Fluid movement pathways and transitions through shared stage space\n• Sustained character, focus, and purpose during movement sequences"},{"sort_order":4,"title":"CONNECTION: Support of Style and World of the Show","description":"• Authentic onstage relationships and responsive interactions\n• Cohesive physical and vocal choices consistent with the show’s genre and tone\n• Appropriate shifts in energy and expression to suit dramatic circumstances\n• Active engagement and supportive focus that establish a believable theatrical world"}]},{"category_key":"technical_execution","criteria":[{"sort_order":1,"title":"FLUIDITY OF TECHNICAL CUES AND STAGE TRANSITIONS","description":"• Accurate, timely lighting, sound, projection, and effects cues\n• Smooth, coordinated scene changes and technical transitions\n• Seamless synchronization with staging, movement, pacing, and dramatic moments\n• Consistent execution without unintended interruptions or distractions"},{"sort_order":2,"title":"CREATIVE COLLABORATION AND TECHNICAL INTEGRATION","description":"• Purposeful technical choices aligned with the director’s vision and storytelling\n• Cohesive integration of lighting, sound, projections, and effects\n• Coordination with performance, choreography, staging, and transitions\n• Creative use of available resources and specialized effects when applicable"},{"sort_order":3,"title":"CREW: Professionalism and Execution","description":"• Prepared, confident, and coordinated execution of visible crew responsibilities\n• Efficient, organized handling of scenery, props, and equipment\n• Focused, discreet conduct that supports the performance\n• Effective response to observable issues and minimal disruption to pacing or story"}]},{"category_key":"lighting_design","criteria":[{"sort_order":1,"title":"FOCAL POINTS: Visibility and Focus","description":"• Clear, intentional visibility of performers’ expressions, movement, and important action when dramatically intended\n• Lighting that guides audience attention and establishes dramatic focal points\n• Effective coverage across skin tones, heights, and physical characteristics\n• Purposeful use of light, shadow, and contrast aligned with staging"},{"sort_order":2,"title":"STORY ELEMENTS: Mood, Tone, and Artistic Design","description":"• Color, intensity, texture, and direction used to establish mood and atmosphere\n• Lighting that communicates setting, time, style, and theatrical world\n• Dynamic choices that underscore emotional shifts and dramatic moments\n• Creative effects, shadows, or specials when they serve the story"},{"sort_order":3,"title":"CREATIVE COLLABORATION","description":"• Lighting aligned with the director’s overall artistic vision\n• Cohesive visual integration with scenery, costumes, sound, and effects\n• Lighting that complements blocking, choreography, and performer movement\n• Coordinated design choices that strengthen dramatic and visual impact"},{"sort_order":4,"title":"EQUIPMENT: Effective Use and Configuration","description":"• Resourceful, effective use of available lighting capabilities\n• Purposeful instrument positioning, focus, and stage coverage\n• Effective programming of intensity, color, timing, and transitions\n• Reliable lighting results across scenes and staging needs"}]},{"category_key":"sound_design","criteria":[{"sort_order":1,"title":"STORY ELEMENTS: Aesthetic and Intentional Use of Sound","description":"• Purposeful sound effects and ambience that establish setting and atmosphere\n• Audio choices that support emotion, dramatic tension, and narrative pacing\n• Well-timed sound transitions integrated with onstage action\n• Stylistically cohesive sound design that deepens audience immersion"},{"sort_order":2,"title":"BALANCE: Between Orchestra/Track and Voices","description":"• Consistently audible, intelligible solo and ensemble vocals\n• Balanced mixing of voices, instruments, and live or recorded accompaniment\n• Responsive levels that accommodate changing voices, dynamics, and ensemble size\n• Clear sound mix that preserves musical expression and storytelling"},{"sort_order":3,"title":"CREATIVE COLLABORATION","description":"• Sound choices aligned with the director’s vision, tone, and pace\n• Cohesive integration with lighting, scenery, and other design elements\n• Coordination with blocking, choreography, and dramatic transitions\n• Purposeful audio integration that supports performers and the theatrical world"},{"sort_order":4,"title":"EQUIPMENT: Effective Use and Setup","description":"• Effective use of available microphones, speakers, and audio equipment\n• Effective microphone placement, clear pickup, and consistent coverage as performers move onstage\n• Intelligible dialogue, singing, music, and effects\n• Reliable operation with minimal unintended feedback, dropouts, or distortion"}]},{"category_key":"scenic_design","criteria":[{"sort_order":1,"title":"STORYTELLING: Through Scenic Concept and Visual Design","description":"• Cohesive scenic concept aligned with the director’s interpretation\n• Visual choices that establish setting, period, style, mood, and themes\n• Purposeful scenery, levels, backdrops, and textures that communicate story\n• Effective visual support of narrative progression and scene changes"},{"sort_order":2,"title":"CONSTRUCTION QUALITY AND FUNCTIONALITY","description":"• Sturdy, stable, and well-finished scenic construction\n• Functional scenery, platforms, furniture, and props that support performance\n• Reliable movement or adaptation of scenic elements during transitions\n• Safe, practical construction that accommodates blocking and choreography"},{"sort_order":3,"title":"USE OF SPACE, LEVELS, AND MOVEMENT PATHWAYS","description":"• Effective use of stage width, depth, height, and levels\n• Scenic composition that supports focus and varied stage pictures\n• Clear, safe pathways for performer movement and choreography\n• Flexible scenic placement that facilitates staging and scene transitions"},{"sort_order":4,"title":"VISUAL STATEMENT: Mediums and Detail","description":"• Intentional materials, colors, textures, and finishes suited to the concept\n• Quality scenic painting, surface treatments, and decorative craftsmanship\n• Cohesive scale, proportion, detail, and visual consistency\n• Imaginative, resourceful visual choices that strengthen the theatrical world"},{"sort_order":5,"title":"CREATIVE COLLABORATION","description":"• Scenery that reinforces the director’s vision and production style\n• Cohesive integration with lighting, costumes, and other design elements\n• Scenic design that complements blocking, choreography, and transitions\n• Creative solutions using available resources to support storytelling"}]},{"category_key":"costume_design","criteria":[{"sort_order":1,"title":"STORY ELEMENTS: Storytelling Through Style, Color, and Period","description":"• Cohesive costume concept aligned with the director’s interpretation\n• Purposeful color, silhouette, fabric, and style to establish the theatrical world\n• Costumes that communicate setting, period or reimagined style, tone, and relevant cultural context\n• Visual storytelling that clarifies characters, relationships, and themes"},{"sort_order":2,"title":"VISUAL STATEMENT: Construction, Fit, and Functionality","description":"• Quality craftsmanship, alterations, tailoring, and finishing\n• Appropriate fit and durability for individual performers\n• Costumes that enable acting, singing, dancing, and confident movement\n• Practical construction and design that accommodate quick changes\n• Cohesive visual execution through material, color, texture, and detail"},{"sort_order":3,"title":"INDIVIDUAL CHARACTERIZATION: Accessories, Hair/Wig, Cohesive Look","description":"• Character-specific costumes that convey age, occupation, personality, status, and relevant circumstances\n• Purposeful accessories, hair, wigs, and details that reinforce characterization\n• Visual distinctions that clarify status, relationships, and character evolution when relevant\n• Integrated, stylistically cohesive character looks suited to performers’ roles and movement"},{"sort_order":4,"title":"CREATIVE COLLABORATION","description":"• Costumes aligned with the director’s vision and overall visual style\n• Cohesive integration with scenery, lighting, and other design elements\n• Costume choices that support characterization, staging, and choreography\n• Practical solutions for movement, quick changes, and technical needs"}]},{"category_key":"leading_actress","criteria":[{"sort_order":1,"title":"CHARACTER DEVELOPMENT & ARC","description":"• Believable character objectives, motivations, and purposeful choices\n• Layered, consistent characterization and emotionally authentic development\n• Active listening, present-moment responses, and dynamic relationships\n• Character evolution that meaningfully supports the narrative arc"},{"sort_order":2,"title":"TECHNICAL/ARTISTIC SKILL: Vocal Technique and Musical Storytelling","description":"• Accurate pitch, timing, breath control, diction, and articulation\n• Purposeful phrasing, dynamics, and stylistically appropriate vocal expression\n• Character-driven interpretation that conveys emotion and advances the story\n• Seamless integration of singing with acting, movement, and dramatic pacing"},{"sort_order":3,"title":"PERFORMANCE: Stage Presence, Focus, Physical Commitment, and Connection","description":"• Compelling presence, sustained focus, and committed, vital performance\n• Purposeful movement, physicality, and expressive dialogue delivery\n• Authentic listening, connection, and responsiveness to scene partners\n• Stylistically appropriate choices that integrate action, emotion, and storytelling"}]},{"category_key":"leading_actor","criteria":[{"sort_order":1,"title":"CHARACTER DEVELOPMENT & ARC","description":"• Believable character objectives, motivations, and purposeful choices\n• Layered, consistent characterization and emotionally authentic development\n• Active listening, present-moment responses, and dynamic relationships\n• Character evolution that meaningfully supports the narrative arc"},{"sort_order":2,"title":"TECHNICAL/ARTISTIC SKILL: Vocal Technique and Musical Storytelling","description":"• Accurate pitch, timing, breath control, diction, and articulation\n• Purposeful phrasing, dynamics, and stylistically appropriate vocal expression\n• Character-driven interpretation that conveys emotion and advances the story\n• Seamless integration of singing with acting, movement, and dramatic pacing"},{"sort_order":3,"title":"PERFORMANCE: Stage Presence, Focus, Physical Commitment, and Connection","description":"• Compelling presence, sustained focus, and committed, vital performance\n• Purposeful movement, physicality, and expressive dialogue delivery\n• Authentic listening, connection, and responsiveness to scene partners\n• Stylistically appropriate choices that integrate action, emotion, and storytelling"}]},{"category_key":"supporting_performer_a","criteria":[{"sort_order":1,"title":"CHARACTER DEVELOPMENT: Character Specificity and Relationships","description":"• Distinct, believable characterization appropriate to the role’s scope\n• Clear objectives, motivations, and emotionally grounded choices\n• Authentic listening and dynamic relationships with scene partners\n• Consistent character choices that meaningfully support the narrative"},{"sort_order":2,"title":"TECHNICAL/ARTISTIC SKILL: Vocal & Movement Technique","description":"• Accurate pitch, rhythm, breath support, diction, and articulation as applicable\n• Controlled, confident movement and choreographic precision\n• Purposeful vocal phrasing, dynamics, and physical expression suited to character and style\n• Integrated technique that supports scene rhythm, pacing, and storytelling"},{"sort_order":3,"title":"CONNECTION: Presence, Timing, and Ensemble Contribution","description":"• Engaging presence with sustained focus and character commitment\n• Authentic responsiveness and effective comedic, dramatic, or musical timing\n• Appropriate focus sharing and support of scene partners\n• Meaningful contributions to ensemble moments and collective storytelling"}]},{"category_key":"supporting_performer_b","criteria":[{"sort_order":1,"title":"CHARACTER DEVELOPMENT: Character Specificity and Relationships","description":"• Distinct, believable characterization appropriate to the role’s scope\n• Clear objectives, motivations, and emotionally grounded choices\n• Authentic listening and dynamic relationships with scene partners\n• Consistent character choices that meaningfully support the narrative"},{"sort_order":2,"title":"TECHNICAL/ARTISTIC SKILL: Vocal & Movement Technique","description":"• Accurate pitch, rhythm, breath support, diction, and articulation as applicable\n• Controlled, confident movement and choreographic precision\n• Purposeful vocal phrasing, dynamics, and physical expression suited to character and style\n• Integrated technique that supports scene rhythm, pacing, and storytelling"},{"sort_order":3,"title":"CONNECTION: Presence, Timing, and Ensemble Contribution","description":"• Engaging presence with sustained focus and character commitment\n• Authentic responsiveness and effective comedic, dramatic, or musical timing\n• Appropriate focus sharing and support of scene partners\n• Meaningful contributions to ensemble moments and collective storytelling"}]},{"category_key":"featured_performer","criteria":[{"sort_order":1,"title":"CHARACTER DEVELOPMENT: Character Impact and Memorability","description":"• Distinct, believable character established within limited stage time\n• Clear objectives and bold, purposeful choices appropriate to the role\n• Authentic relationships and expressive vocal or physical characterization\n• Meaningful, memorable contribution to the scene and larger narrative"},{"sort_order":2,"title":"TECHNICAL/ARTISTIC SKILL: Vocal and Physical Expression","description":"• Clear, controlled vocal delivery; accurate pitch and timing when singing\n• Effective breath support, diction, articulation, and phrasing as applicable\n• Confident, precise physical movement, gesture, and rhythmic awareness\n• Character-specific, stylistically appropriate vocal and physical expression that strengthens brief dramatic moments"},{"sort_order":3,"title":"PERFORMANCE: Timing, Focus, and Scene Awareness","description":"• Sustained presence, focus, and consistent in-character behavior\n• Effective dramatic/comedic timing, cue pickup, and responsive delivery\n• Authentic listening, emotional responsiveness, and spatial awareness\n• Appropriate focus sharing and contribution to ensemble flow and storytelling"}]},{"category_key":"direction","criteria":[{"sort_order":1,"title":"ARTISTIC VISION: Unification of Staging, Design, Tone, and Drive","description":"• Clear, cohesive directorial vision sustained throughout the production\n• Unified staging, performances, design elements, and theatrical style\n• Purposeful pacing and momentum across scenes and musical numbers\n• Consistent visual and emotional throughline that enhances storytelling"},{"sort_order":2,"title":"STORY DEPICTION: Structure, Author’s Intent, Style, Setting, Cultural Background","description":"• Thoughtful interpretation of script structure, themes, and central message\n• Attention to historical, cultural, and social context when relevant\n• Consistent, purposeful style and staging that establish the show’s world\n• Traditional or reimagined choices that honor the author’s storytelling intent and preserve narrative clarity and integrity"},{"sort_order":3,"title":"CASTING: Role Suitability, Character Authenticity, and Ensemble Cohesion","description":"• Casting that matches vocal, physical, and acting abilities to role demands while using performers’ strengths\n• Believable character portrayals and relationships across the company\n• Cohesive casting that supports the production’s tone, vision, and storytelling\n• Effective ensemble dynamics and distribution of dramatic and musical responsibilities"},{"sort_order":4,"title":"STAGE SPACE: Blocking and Use","description":"• Purposeful blocking reflecting character objectives and relationships\n• Effective use of space, levels, stage pictures, and audience focus\n• Fluid entrances, exits, movement pathways, and scene transitions\n• Blocking integrated with scenery, lighting, choreography, and dramatic pacing"},{"sort_order":5,"title":"MAIN CHARACTER DEVELOPMENT","description":"• Clear, layered principal-character motivations, objectives, and emotional journeys\n• Clear, articulated dialogue and purposeful vocal expression\n• Safe, grounded physical staging that supports believable relationships and reactions\n• Authentic reactions and dramatic pacing that support character development\n• Individual character arcs integrated with the overall story and director’s vision"},{"sort_order":6,"title":"ENSEMBLE CHARACTER DEVELOPMENT","description":"• Distinct ensemble character intentions, behaviors, and relationships\n• Consistent focus and engagement, including background action\n• Individual choices shaped into cohesive, purposeful ensemble storytelling\n• Appropriate focus sharing, movement, and energy that support dramatic flow"}]}]$criteria$::jsonb;
  target_rubric_id uuid;
  target_rubric_count integer;
  category_payload jsonb;
  criterion_payload jsonb;
  target_category_id uuid;
  current_criteria_count integer;
  affected_rows integer;
  updated_criteria_count integer := 0;
begin
  select count(*)
  into target_rubric_count
  from public.scoring_rubrics rubric
  join public.award_cycles cycle on cycle.id = rubric.cycle_id
  where cycle.season_year = '2026-2027'
    and cycle.name = '2026–2027 Director Application'
    and rubric.status = 'published';

  if target_rubric_count <> 1 then
    raise exception 'Expected exactly one published 2026–2027 Director Application rubric; found %.', target_rubric_count;
  end if;

  select rubric.id
  into target_rubric_id
  from public.scoring_rubrics rubric
  join public.award_cycles cycle on cycle.id = rubric.cycle_id
  where cycle.season_year = '2026-2027'
    and cycle.name = '2026–2027 Director Application'
    and rubric.status = 'published';

  if jsonb_array_length(criteria_payload) <> 15 then
    raise exception 'Expected 15 rubric categories in the quick-reference payload.';
  end if;

  for category_payload in
    select value from jsonb_array_elements(criteria_payload)
  loop
    select category.id
    into target_category_id
    from public.scoring_categories category
    where category.rubric_id = target_rubric_id
      and category.category_key = category_payload ->> 'category_key'
      and category.active = true;

    if target_category_id is null then
      raise exception 'Active rubric category % was not found.', category_payload ->> 'category_key';
    end if;

    select count(*)
    into current_criteria_count
    from public.scoring_criteria criterion
    where criterion.category_id = target_category_id
      and criterion.active = true;

    if current_criteria_count <> jsonb_array_length(category_payload -> 'criteria') then
      raise exception 'Criterion count mismatch for %: database %, reference %.',
        category_payload ->> 'category_key',
        current_criteria_count,
        jsonb_array_length(category_payload -> 'criteria');
    end if;

    for criterion_payload in
      select value from jsonb_array_elements(category_payload -> 'criteria')
    loop
      update public.scoring_criteria criterion
      set
        title = criterion_payload ->> 'title',
        description = criterion_payload ->> 'description'
      where criterion.category_id = target_category_id
        and criterion.sort_order = (criterion_payload ->> 'sort_order')::integer
        and criterion.active = true;

      get diagnostics affected_rows = row_count;
      if affected_rows <> 1 then
        raise exception 'Expected one active criterion for % at order %; updated %.',
          category_payload ->> 'category_key',
          criterion_payload ->> 'sort_order',
          affected_rows;
      end if;

      updated_criteria_count := updated_criteria_count + 1;
    end loop;
  end loop;

  if updated_criteria_count <> 58 then
    raise exception 'Expected to update 58 rubric criteria; updated %.', updated_criteria_count;
  end if;

  update public.scoring_rubrics
  set updated_at = now()
  where id = target_rubric_id;
end;
$$;
